{
}

Method.Source:
    /// <summary>
    /// Update on close of Form
    /// </summary>
    public void closeOk()
    {
        PurchQty    metOrigRemainPurchPhysical  = callerPurchLine.RemainPurchPhysical;
        InventQty   metOrigRemainInventPhysical = callerPurchLine.RemainInventPhysical;
        
        next closeOk();

        callerPurchLine.reread();

        if(   metOrigRemainPurchPhysical != callerPurchLine.RemainPurchPhysical 
           || metOrigRemainInventPhysical != callerPurchLine.RemainInventPhysical)
        {
            callerPurchLine.metPurchLine().updateIntegrationStatus(METIntegrationStatus::ReadyToSend);
            callerPurchLine.purchTable().metPurchTable().updateIntegrationStatus(METIntegrationStatus::ReadyToSend);
        }
    }
